28	template <class vertex>
29	struct PR_F {
30	  double* p_curr, *p_next;
31	  vertex* V;
32	  PR_F(double* _p_curr, double* _p_next, vertex* _V) :
33	    p_curr(_p_curr), p_next(_p_next), V(_V) {}
34	  inline bool update(uintE s, uintE d){ //update function applies PageRank equation
35	    p_next[d] += p_curr[s]/V[s].getOutDegree();
36	    return 1;
37	  }
38	  inline bool updateAtomic (uintE s, uintE d) { //atomic Update
39	    writeAdd(&p_next[d],p_curr[s]/V[s].getOutDegree());
40	    return 1;
41	  }
42	  inline bool cond (intT d) { return cond_true(d); }
43	};
