426	// Returns the subset of V where filter(v) is true. Uses a sparse
427	// representation (a packed array of vertex ids) for the result.
428	template <class F>
429	vertexSubset vertexFilter2(vertexSubset V, F filter) {
430	  long n = V.numRows(), m = V.numNonzeros();
431	  if (m == 0) {
432	    return vertexSubset(n);
433	  }
434	  bool* bits = newA(bool, m);
435	  V.toSparse();
436	  {parallel_for(size_t i=0; i<m; i++) {
437	    uintE v = V.vtx(i);
438	    bits[i] = filter(v);
439	  }}
440	  auto v_imap = make_in_imap<uintE>(m, [&] (size_t i) { return V.vtx(i); });
441	  auto bits_m = make_in_imap<bool>(m, [&] (size_t i) { return bits[i]; });
442	  auto out = pbbs::pack(v_imap, bits_m);
443	  out.alloc = false;
444	  free(bits);
445	  return vertexSubset(n, out.size(), out.s);
446	}
