// Maximal independent set (MIS) on a symmetric graph, computed with the
// round-based "lexicographically-first" algorithm.
//
// Every vertex is in one of three states, held in the flags array:
//   0 (UNDECIDED)  not yet placed in or out of the set,
//   1 (IN)         in the MIS,
//   2 (OUT)        excluded, because a neighbor is in the MIS.
//
// A round proceeds in three phases:
//   (a) the root set is every still-undecided vertex that has NO undecided
//       neighbor with a smaller vertex id.  Two root-set vertices can never be
//       adjacent (of an adjacent pair, the larger one sees the smaller one as an
//       undecided smaller neighbor), so the whole root set can be added to the
//       MIS at once.
//   (b) the root set is marked IN.
//   (c) an edgeMap out of the root set marks every undecided neighbor of a root
//       OUT.  Roots are already IN at that point, so cond() shields them.
// The undecided set shrinks every round -- the smallest undecided id is always
// a root -- so the loop terminates, and the result is exactly the set produced
// by the sequential greedy scan "visit vertices in increasing id order, add the
// vertex if no neighbor has already been added".
//
// The "no smaller undecided neighbor" test is done with countOutNgh rather than
// by walking a neighbor array, so the code also works on compressed (Ligra+)
// vertices.
#include "ligra.h"
#include <fstream>

// Vertex states.
#define MIS_UNDECIDED 0
#define MIS_IN 1
#define MIS_OUT 2

// Phase (a): is v a root, i.e. does v have no undecided neighbor with a
// smaller id?  Applied through vertexFilter to the undecided frontier.
template <class vertex>
struct MIS_Root_F {
  vertex* V;
  intE* flags;
  MIS_Root_F(vertex* _V, intE* _flags) : V(_V), flags(_flags) {}
  inline bool operator () (uintE v) {
    intE* fl = flags;
    // countOutNgh takes its predicate by reference, hence the named lambda.
    auto smallerUndecided = [&] (uintE src, uintE ngh) {
      return (ngh < src) && (fl[ngh] == MIS_UNDECIDED);
    };
    return V[v].countOutNgh(v, smallerUndecided) == 0;
  }
};

// Phase (b): move a root into the MIS.
struct MIS_Add_F {
  intE* flags;
  MIS_Add_F(intE* _flags) : flags(_flags) {}
  inline bool operator () (uintE v) { flags[v] = MIS_IN; return 1; }
};

// Phase (c): every undecided neighbor of a vertex in the MIS is excluded.
struct MIS_Exclude_F {
  intE* flags;
  MIS_Exclude_F(intE* _flags) : flags(_flags) {}
  inline bool update (uintE s, uintE d) { //Update
    flags[d] = MIS_OUT; return 1;
  }
  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
    return CAS(&flags[d],(intE)MIS_UNDECIDED,(intE)MIS_OUT);
  }
  //only undecided vertices can still be excluded
  inline bool cond (uintE d) { return flags[d] == MIS_UNDECIDED; }
};

// Keeps the vertices that are still undecided at the end of a round.
struct MIS_Undecided_F {
  intE* flags;
  MIS_Undecided_F(intE* _flags) : flags(_flags) {}
  inline bool operator () (uintE v) { return flags[v] == MIS_UNDECIDED; }
};

template <class vertex>
void Compute(graph<vertex>& GA, commandLine P) {
  const long n = GA.n;
  //flags[v] holds the state of v; everything starts out undecided
  intE* flags = newA(intE,n);
  {parallel_for(long i=0;i<n;i++) flags[i] = MIS_UNDECIDED;}

  //the frontier always holds exactly the undecided vertices
  bool* undecided = newA(bool,n);
  {parallel_for(long i=0;i<n;i++) undecided[i] = 1;}
  vertexSubset Frontier(n,n,undecided);

  long rounds = 0;   //number of root-set rounds
  long MISsize = 0;  //number of vertices placed in the MIS
  while(!Frontier.isEmpty()) {
    rounds++;
    // vertexFilter takes its argument by value and densifies the copy, so
    // materialize the dense array here to keep ownership in Frontier.
    Frontier.toDense();
    // (a) undecided vertices with no smaller undecided neighbor
    vertexSubset roots = vertexFilter(Frontier,MIS_Root_F<vertex>(GA.V,flags));
    // (b) the whole root set joins the MIS
    vertexMap(roots,MIS_Add_F(flags));
    MISsize += roots.numNonzeros();
    // (c) exclude the undecided neighbors of the new MIS vertices
    edgeMap(GA,roots,MIS_Exclude_F(flags),-1,no_output);
    roots.del();
    // (d) drop the vertices that were decided this round
    vertexSubset remaining = vertexFilter(Frontier,MIS_Undecided_F(flags));
    Frontier.del();
    Frontier = remaining;
  }
  Frontier.del();

  cout << "MIS rounds: " << rounds << endl;
  cout << "MIS size: " << MISsize << endl;

  //optionally dump the chosen vertices, one id per line, for verification
  string outFileName = P.getOptionValue("-outfile","");
  if(outFileName != "") {
    ofstream outFile(outFileName.c_str());
    if(outFile.is_open()) {
      for(long i=0;i<n;i++) if(flags[i] == MIS_IN) outFile << i << endl;
      outFile.close();
    } else cout << "MIS: could not open " << outFileName << endl;
  }

  free(flags);
}
